// Construye el prompt de sistema (ver agente-choferes/prompt-sistema.md)
// y el historial de mensajes para Claude.
const hook = $('Webhook').first().json;
const entrada = hook.body || hook;
const telefono = String(entrada.telefono || '').trim();
const mensaje = String(entrada.mensaje || '').trim();
if (!telefono || !mensaje) {
  throw new Error('El webhook necesita { telefono, mensaje }');
}

let estado = {};
try {
  const sesiones = $('Cargar sesión').all().map((i) => i.json).filter((x) => x && x.telefono);
  if (sesiones.length) estado = sesiones[0].estado || {};
} catch (e) { /* primera conversación de este teléfono */ }
const historial = Array.isArray(estado.historial) ? estado.historial : [];

const productos = $('Cargar productos').all().map((i) => i.json).filter((x) => x && x.id);
const tiendas = $('Cargar tiendas').all().map((i) => i.json).filter((x) => x && x.id);

const sistema = [
  'Eres el asistente de reparto de Minis by Mónica. Hablas por WhatsApp con los choferes que visitan supermercados. Tu único trabajo es registrar el inventario de cada visita a tienda, completo y sin fricción. Tono cercano y breve, como se habla por WhatsApp.',
  '',
  'PRODUCTOS del checklist (id, nombre, nivel par). Hay que contar TODOS, sin excepción:',
  JSON.stringify(productos),
  '',
  'TIENDAS activas (id, nombre, chofer_id de la ruta):',
  JSON.stringify(tiendas),
  '',
  'FLUJO: (1) identifica la tienda que el chofer menciona (acepta nombres aproximados; si no la reconoces, pregunta, nunca inventes). (2) Pide el conteo de lo que QUEDA en el exhibidor antes de reponer; acepta texto libre en cualquier orden y estructúralo tú; "no queda" o "se acabó" cuenta como 0. (3) REGLA DE ORO: la visita NO se cierra hasta tener el conteo de TODOS los productos del checklist; si faltan, di exactamente cuáles faltan y pide solo esos. (4) Con todos los conteos, muestra el resumen y pide confirmación antes de cerrar. (5) Si el chofer menciona cuánto DEJÓ de cada producto, regístralo en cantidad_dejada; si no, null y no insistas más de una vez. (6) Si un producto quedó por debajo de la MITAD de su nivel par, genera una alerta con tienda y producto.',
  '',
  'FORMATO OBLIGATORIO: responde SIEMPRE y SOLO con un JSON válido, sin texto fuera del JSON y sin bloques de código:',
  '{"respuesta": "mensaje corto para el chofer", "accion": "ninguna" | "guardar_visita", "visita": {"tienda_id": 0, "notas": "", "conteos": [{"producto_id": 0, "cantidad_encontrada": 0, "cantidad_dejada": null}]} | null, "alertas": [{"tienda_id": 0, "producto_id": 0, "mensaje": "..."}]}',
  '',
  'accion es "guardar_visita" ÚNICAMENTE cuando están los conteos de todos los productos del checklist Y el chofer confirmó el resumen. Nunca cierres una visita incompleta, aunque el chofer insista: explícale con buen humor que la oficina necesita los datos completos.',
].join('\n');

const messages = [...historial, { role: 'user', content: mensaje }].slice(-30);

return [{ json: { telefono, mensaje, sistema, messages } }];

// Interpreta el JSON del agente y prepara la sesión actualizada.
const prep = $('Preparar consulta').first().json;
const resp = $('Claude').first().json;
const texto = (resp.content || []).map((b) => b.text || '').join('').trim();

let salida;
try {
  salida = JSON.parse(texto.replace(/^```json?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  salida = { respuesta: texto || 'Disculpa, no te entendí. ¿Me lo repites?', accion: 'ninguna', visita: null, alertas: [] };
}

const historial = [...prep.messages, { role: 'assistant', content: texto }].slice(-30);

return [{
  json: {
    respuesta: String(salida.respuesta || '...'),
    accion: salida.accion === 'guardar_visita' && salida.visita ? 'guardar_visita' : 'ninguna',
    visita: salida.visita || null,
    alertas: Array.isArray(salida.alertas) ? salida.alertas : [],
    sesion: {
      telefono: prep.telefono,
      estado: { historial },
      actualizada_en: new Date().toISOString(),
    },
  },
}];
